```ts
import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { createFreeCamera, attachFreeControl } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };

export interface Walkthrough {
  readonly camera: FreeCamera;
  jumpTo(eye: Vec, target: Vec): void;
  dispose(): void;
}

export function createWalkthrough(
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  eye: Vec,
  target: Vec,
): Walkthrough {
  const camera = createFreeCamera(eye, target);
  scene.camera = camera;
  const disposeControl = attachFreeControl(camera, canvas, scene);

  function jumpTo(eye: Vec, target: Vec): void {
    camera.position.x = eye.x;
    camera.position.y = eye.y;
    camera.position.z = eye.z;

    const dx = target.x - eye.x;
    const dy = target.y - eye.y;
    const dz = target.z - eye.z;

    camera._yaw = Math.atan2(dx, dz);
    camera._pitch = Math.atan2(dy, Math.sqrt(dx * dx + dz * dz));

    camera.target.x = target.x;
    camera.target.y = target.y;
    camera.target.z = target.z;
  }

  function dispose(): void {
    disposeControl();
  }

  return { camera, jumpTo, dispose };
}
```

I created `src/walkthrough.ts` which builds a free camera at the given eye/target, sets it as `scene.camera`, attaches the standard free-control (keyboard + mouse) via `attachFreeControl`, and provides `jumpTo` that repositions the camera and updates its internal `_yaw`/`_pitch` so the controls carry on from the new orientation (per notes 5 and 52, the controls derive movement direction from those fields, not from `target` alone). `dispose` calls the returned detach function, which removes the canvas listeners and the `_beforeRender` frame hook.

One thing I was not sure of: whether `SceneContext` exposes a `camera` property for assignment (the `.d.ts` you provided doesn't include the full `SceneContext` interface), but since you stated the camera should be `scene.camera`, I set it directly.
